#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Assuming Image and KURL types are defined elsewhere
// and that clipboard_write_image, clipboard_write_bookmark, clipboard_write_html,
// and clipboard_commit are defined functions.

void write_image_to_clipboard(Image* image, const KURL* url, const char* title) {
    if (!image) {
        return;
    }

    void* bitmap = image->get_bitmap();
    if (!bitmap) {
        return;
    }

    clipboard_write_image(bitmap);

    if (url && url->is_valid()) {
        char* bookmark = malloc(1024);
        if (bookmark) {
            snprintf(bookmark, 1024, "Bookmark: %s, Title: %s", url->get_url(), title);
            clipboard_write_bookmark(bookmark);
            free(bookmark);
        }

        char* html = malloc(2048);
        if (html) {
            snprintf(html, 2048, "<img src=\"%s\" title=\"%s\">", url->get_url(), title);
            clipboard_write_html(html);
            free(html);
        }
    }

    clipboard_commit();
}
